package com.servicerca.service; import com.servicerca.dto.notification.PushSubscriptionRequest;import com.servicerca.model.*;import com.servicerca.repository.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class NotificationService{private final PushSubscriptionRepository subscriptions;public NotificationService(PushSubscriptionRepository s){subscriptions=s;}@Transactional public void subscribe(User user,PushSubscriptionRequest r){var s=subscriptions.findByEndpoint(r.endpoint()).orElseGet(PushSubscription::new);s.setUser(user);s.setEndpoint(r.endpoint());s.setP256dh(r.p256dh());s.setAuth(r.auth());subscriptions.save(s);}@Transactional public void unsubscribe(String endpoint){subscriptions.findByEndpoint(endpoint).ifPresent(subscriptions::delete);}}
